var t=`0794-pilao-comorien`;var o=`world-0794`;var n=`KM`;var r=`eastern-africa`;var a=4;var s=57;var g={en:`Pilao Comorien`,ua:`Коморський пілау`};var l={en:`Pilao Comorien is a Comoros classic prepared with yellow onion, garlic, ginger root, basmati rice. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Коморський пілау, страва кухні країни Коморські Острови зі складниками: жовта цибуля, часник, корінь імбиру, рис басматі. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,190,`g`],[`garlic`,4,`clove`],[`ginger-root`,22,`g`],[`sunflower-oil`,45,`ml`],[`ground-cumin`,5,`g`]]},{en:`Coat the rice in the warm fat with the aromatics and toast gently for about 5 minutes without browning.`,ua:`Змішайте рис із теплим жиром та ароматичними складниками й прогрівайте приблизно 5 хвилин, не підрум’янюючи.`,t:[`sauteing`,`risotto-method`],m:5,i:[[`basmati-rice`,400,`g`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 28 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 28 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:28,i:[[`coconut-milk`,300,`ml`],[`chicken-stock`,470,`ml`],[`ground-cardamom`,4,`g`],[`ground-cloves`,2,`g`]]},{en:`Take off the heat and let the rice rest under a clean towel or lid for about 9 minutes before serving.`,ua:`Зніміть із вогню та дайте рису відпочити під чистим рушником або кришкою приблизно 9 хвилин перед подаванням.`,t:[`rice-resting`,`fluffing-grains`],m:9,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`raisin`,70,`g`]]}];var d={slug:t,id:o,country:`KM`,region:r,servings:4,minutes:57,title:g,text:l,steps:u};export{n as country,d as default,o as id,s as minutes,r as region,a as servings,t as slug,u as steps,l as text,g as title};